public class LocalizedSamplingStrategy implements SamplingStrategy { @Override public SamplingResponse shouldTrace(SamplingRequest samplingRequest) { if (logger.isDebugEnabled()) { logger.debug("Determining shouldTrace decision for:
	host: " + samplingRequest.getHost().orElse("") + "
	path: " + samplingRequest.getUrl().orElse("") + "
	method: " + samplingRequest.getMethod().orElse("")); } SamplingResponse sampleResponse = new SamplingResponse(); SamplingRule firstApplicableRule = null; if (rules != null) { firstApplicableRule = rules.stream().filter(rule -> rule.appliesTo(samplingRequest.getHost().orElse(""), samplingRequest.getUrl().orElse(""), samplingRequest.getMethod().orElse(""))).findFirst().orElse(null); } sampleResponse.setSampled(firstApplicableRule == null ? shouldTrace(defaultRule) : shouldTrace(firstApplicableRule)); return sampleResponse; } public LocalizedSamplingStrategy(); public LocalizedSamplingStrategy(@Nullable URL ruleLocation); public LocalizedSamplingStrategy(boolean forcedSamplingSupport); public LocalizedSamplingStrategy(@Nullable URL ruleLocation, boolean forcedSamplingSupport); @Nullable public URL getSamplingManifestURL(); @Override public SamplingResponse shouldTrace(SamplingRequest samplingRequest); @Override public boolean isForcedSamplingSupported(); static final URL DEFAULT_RULES; }

